// Validate that the required environment variable is set before running any request
const baseUrl = pm.environment.get("url");

if (!baseUrl) {
    throw new Error("Environment variable 'url' is not defined. Please set it in the active environment before running this collection.");
}

// Defines the schemas and saves them as collection variables:
// User Created
const createUserSchema = {
    type: "object",
    required: ["message", "_id"],
    properties: {
        message:  { type: "string" },
        _id:   { type: "string" }
    }
};

pm.collectionVariables.set("createUserSchema", JSON.stringify(createUserSchema));

// Login With Valid Credential
const loginSchema = {
    type: "object",
    required: ["message", "authorization"],
    properties: {
        message:  { type: "string" },
        _id:   { type: "string" }
    }
};

pm.collectionVariables.set("loginSchema", JSON.stringify(loginSchema));

// Login With Invalid Credential
const loginInvalidSchema = {
    type: "object",
    required: ["message"],
    properties: {
        message:  { type: "string" }
    }
};

pm.collectionVariables.set("loginInvalidSchema", JSON.stringify(loginInvalidSchema));

// Login With Empty Credential
const loginEmptySchema = {
    type: "object",
    required: ["email", "password"],
    properties: {
        email:  { type: "string" },
        password: { type: "string" }
    }
};

pm.collectionVariables.set("loginEmptySchema", JSON.stringify(loginEmptySchema));
